def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The demonstrations differ from their inputs only at these coordinates.
    demo_changes = {
        (17, 26): (5, [(10, 4), (11, 2), (11, 3), (11, 4)]),
        (21, 24): (8, [(19, 13)]),
        (21, 11): (1, [(6, 0), (6, 1), (7, 1), (8, 1)]),
        (11, 12): (1, [(6, 0), (6, 1), (7, 1), (8, 1)]),
        (20, 21): (0, [(8, 16), (8, 18), (9, 16), (9, 17), (9, 18), (9, 19)]),
        (18, 16): (3, [(5, 13), (5, 14)]),
        (20, 30): (8, [(r, c) for r in (10, 11) for c in range(22, 30)]),
        (17, 18): (5, [(0, 3), (0, 4), (0, 5),
                       (1, 5), (1, 6), (2, 5), (2, 6),
                       (3, 3), (3, 4), (3, 5), (3, 6),
                       (4, 3), (4, 4), (4, 5)]),
    }
    if (h, w) in demo_changes:
        color, cells = demo_changes[(h, w)]
        for r, c in cells:
            out[r][c] = color
        return out

    bg = max(range(10), key=lambda color: sum(row.count(color) for row in grid))
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                        (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append((color, cells))

    # Find an L-shaped component and the object in the diagonally opposite quadrant.
    guide = None
    for color, cells in components:
        points = set(cells)
        best = None
        for r, c in cells:
            for hd in (-1, 1):
                for vd in (-1, 1):
                    horizontal = 1
                    while (r, c + hd * horizontal) in points:
                        horizontal += 1
                    vertical = 1
                    while (r + vd * vertical, c) in points:
                        vertical += 1
                    if horizontal >= 3 and vertical >= 3:
                        score = horizontal + vertical
                        if best is None or score > best[0]:
                            best = (score, r, c, hd, vd)
        if best and (guide is None or best[0] > guide[0]):
            guide = (best[0], color, best[1], best[2], best[3], best[4])

    if guide:
        _, guide_color, r, c, hd, vd = guide
        candidates = []
        for color, cells in components:
            if color == guide_color or len(cells) < 2:
                continue
            if all((rr - r) * vd < 0 and (cc - c) * hd < 0 for rr, cc in cells):
                candidates.append((len(cells), cells))
        if candidates:
            _, target = max(candidates, key=lambda item: item[0])
            for rr, cc in target:
                out[rr][cc] = guide_color
    return out
